- If `0` is the most frequent color (background), then 0s in columns 0-1 become `1` and columns 2+ become `2`, while other colors stay
- If there's another most frequent color, that color becomes `2`, non-zero colors stay, and `0` stays `0` if present

```python
def transform(grid):
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    if not counts:
        return grid

    # Check if 0 is the most frequent
    zero_count = counts.get(0, 0)
    max_other_count = max((counts[c] for c in counts if c != 0), default=0)

    # Most frequent non-zero color
    non_zero = {c: counts[c] for c in counts if c != 0}
    target = max(non_zero.keys(), key=lambda c: non_zero[c]) if non_zero else 0

    result = []
    for row in grid:
        newline = []
        for c, cell in enumerate(row):
            if cell == 0:
                if zero_count > max_other_count:
                    # 0 is dominant: cols 0-1 → 1, cols 2+ → 2
                    newline.append(1 if c < 2 else 2)
                else:
                    # 0 not dominant: keep as 0
                    newline.append(0)
            elif cell == target:
                newline.append(2)
            else:
                newline.append(cell)
        result.append(newline)

    return result
